        'docs.install.body': 'Lade die <code>.mcpack</code>-Datei herunter, benenne sie bei Bedarf mit ZArchiver um, sodass sie auf <code>.mcpack</code> endet, und öffne sie dann, um sie in Minecraft zu importieren. Aktiviere sie anschließend unter <strong>Globale Ressourcen</strong>.',
        'docs.install.faqLink': 'Vollständige Schritt-für-Schritt-Anleitungen für Mobile, PC und Konsole findest du in den <a href="/faq" data-section="faq">FAQ</a>.',
        'docs.config.title': 'Konfiguration',
        'docs.config.body': 'Bearbeite <code>config.json</code> direkt oder nutze den Online-<a href="https://config.glacierclient.xyz/" target="_blank" rel="noopener">Config-Editor</a>. Umschalter verwenden <code>true</code>/<code>false</code>, Deckkraft nutzt <code>0.0</code>&ndash;<code>1.0</code>, und Offsets passen die Position der HUD-Elemente an.',
