        'license.sub': 'Diese Lizenz regelt deine Nutzung der Assets, des Codes und der zugehörigen Inhalte von Glacier Client. Durch das Herunterladen, Überprüfen oder Aufbauen auf Glacier Client stimmst du den untenstehenden Bedingungen zu.',
