        'bedrock.q1': 'Was macht einen Bedrock-Client zum „besten"?',
        'bedrock.q1.body': 'Der beste Minecraft-Bedrock-Client ist sicher auf Realms und Vanilla-Servern nutzbar, injiziert keinen Code und gewährt keine Spielvorteile, und bleibt leichtgewichtig genug für Mobilgeräte. Achte auf einen Resource-Pack-basierten Ansatz, aktive Updates im Takt mit Minecrafts eigenen Releases, und ein HUD, das du wirklich anpassen kannst.',
        'bedrock.q2': 'Wo Glacier Client hineinpasst',
        'bedrock.q2.body': 'Glacier Client ist ein kostenloses Resource-Pack für Minecraft Bedrock Edition mit 37+ Modulen, einem verschiebbaren HUD und einem Config-Editor, komplett auf Minecrafts unterstütztem Resource-Pack-System aufgebaut statt auf Code-Injection. Es läuft auf Mobile, PC und Konsole (via Realms), bei rund 2 MB ohne messbare Performance-Kosten.',
