        'bedrock.title': 'El mejor cliente de Minecraft Bedrock',
        'bedrock.sub': 'Qué buscar en un cliente de Bedrock, y dónde encaja Glacier',
        'bedrock.q1': '¿Qué hace que un cliente de Bedrock sea "el mejor"?',
        'bedrock.q1.body': 'El mejor cliente de Minecraft Bedrock es seguro de usar en Realms y servidores vanilla, no inyecta código ni otorga ventajas de juego, y se mantiene lo suficientemente ligero para funcionar en dispositivos móviles. Busca un enfoque basado en resource packs, actualizaciones activas que sigan el ritmo de los lanzamientos de Minecraft, y un HUD que realmente puedas personalizar.',
        'bedrock.q2': 'Dónde encaja Glacier Client',
        'bedrock.q2.body': 'Glacier Client es un resource pack gratuito para Minecraft Bedrock Edition con 37+ módulos, un HUD arrastrable y un editor de configuración, construido enteramente sobre el sistema de resource packs compatible de Minecraft en lugar de inyección de código. Funciona en Móvil, PC y Consola (vía Realms), con alrededor de 2 MB y sin costo de rendimiento medible.',
