        'docs.install.title': 'Instalación',
        'docs.install.body': 'Descarga el archivo <code>.mcpack</code>, renómbralo si es necesario con ZArchiver para que termine en <code>.mcpack</code>, y ábrelo para importarlo a Minecraft. Actívalo después en <strong>Recursos globales</strong>.',
        'docs.install.faqLink': 'Encontrarás instrucciones completas paso a paso para Móvil, PC y Consola en las <a href="/faq" data-section="faq">FAQ</a>.',
        'docs.config.title': 'Configuración',
        'docs.config.body': 'Edita <code>config.json</code> directamente, o usa el <a href="https://config.glacierclient.xyz/" target="_blank" rel="noopener">Editor de configuración</a> en línea. Los interruptores usan <code>true</code>/<code>false</code>, la opacidad usa <code>0.0</code>&ndash;<code>1.0</code>, y los desplazamientos ajustan la posición de los elementos del HUD.',
