        'docs.troubleshoot.body': 'La mayoría de los problemas provienen de packs de recursos en conflicto o restricciones del lado del servidor. Consulta la <a href="/faq" data-section="faq">sección de solución de problemas de las FAQ</a> para soluciones, o reporta un error en nuestro <a href="https://discord.glacierclient.xyz" target="_blank" rel="noopener">servidor de Discord</a>.',
        'license.sub': 'Esta licencia rige tu uso de los recursos, el código y el contenido asociado de Glacier Client. Al descargar, revisar o construir sobre Glacier Client, aceptas los términos a continuación.',
