        'bedrock.title': 'Meilleur client Minecraft Bedrock',
        'bedrock.sub': 'Ce qu\'il faut rechercher dans un client Bedrock, et où Glacier se situe',
        'bedrock.q1': 'Qu\'est-ce qui fait qu\'un client Bedrock est « le meilleur » ?',
        'bedrock.q1.body': 'Le meilleur client Minecraft Bedrock est sûr à utiliser sur les Realms et les serveurs vanilla, n\'injecte pas de code et ne confère pas d\'avantages de jeu, tout en restant assez léger pour fonctionner sur des appareils mobiles. Recherchez une approche basée sur les resource packs, des mises à jour actives suivant le rythme des propres sorties de Minecraft, et un HUD que vous pouvez réellement personnaliser.',
        'bedrock.q2': 'Où se situe Glacier Client',
        'bedrock.q2.body': 'Glacier Client est un resource pack gratuit pour Minecraft Bedrock Edition avec 37+ modules, un HUD déplaçable et un éditeur de configuration, entièrement construit sur le système de resource packs pris en charge par Minecraft plutôt que sur l\'injection de code. Il fonctionne sur Mobile, PC et Console (via Realms), pour environ 2 Mo sans coût de performance mesurable.',
