        'bedrock.q1.body': 'Il miglior client Minecraft Bedrock è sicuro da usare su Realms e server vanilla, non inietta codice né concede vantaggi di gioco, e rimane abbastanza leggero da funzionare su dispositivi mobili. Cerca un approccio basato su resource pack, aggiornamenti attivi che seguono il ritmo delle release di Minecraft, e un HUD che puoi davvero personalizzare.',
