        'bedrock.q2.body': 'Glacier Client è un resource pack gratuito per Minecraft Bedrock Edition con 37+ moduli, un HUD trascinabile e un editor di configurazione, costruito interamente sul sistema di resource pack supportato da Minecraft anziché sull\'iniezione di codice. Funziona su Mobile, PC e Console (tramite Realms), con circa 2 MB e nessun costo di prestazioni misurabile.',
